import { z } from "zod";

/** Generated by scripts/build_map.ts. Coordinates are map units (1 unit = 100 m), Y down. */
export const berlinMapSchema = z.object({
  width: z.number(),
  height: z.number(),
  districts: z.array(
    z.object({ name: z.string(), path: z.string(), label: z.tuple([z.number(), z.number()]) }),
  ),
  /** Marker positions of the playable places. */
  places: z.array(z.object({ id: z.string(), x: z.number(), y: z.number() })),
});
export type BerlinMap = z.infer<typeof berlinMapSchema>;
